 			return nil, err
 		}
 		return sumPoint(r, sum, r.StartTime(), r.EndTime(), exportSelector.ExportKindFor(r.Descriptor(), aggregation.SumKind), r.Descriptor().InstrumentKind().Monotonic())

 	case aggregation.LastValueKind:
 		lv, ok := agg.(aggregation.LastValue)
 		if !ok {
 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
 		}
 		value, tm, err := lv.LastValue()
 		if err != nil {
 			return nil, err
 		}
 		return gaugePoint(r, value, time.Time{}, tm)

 	case aggregation.ExactKind:
 		e, ok := agg.(aggregation.Points)
 		if !ok {
 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
 		}
 		pts, err := e.Points()
 		if err != nil {
 			return nil, err
 		}

 		return gaugeArray(r, pts)

 	default:
 		return nil, fmt.Errorf("%w: %T", ErrUnimplementedAgg, agg)
 	}
 }

 func gaugeArray(record export.Record, points []aggregation.Point) (*metricpb.Metric, error) {
 	desc := record.Descriptor()
 	labels := record.Labels()
 	nk := desc.NumberKind()
 	m := &metricpb.Metric{
 		Name:        desc.Name(),
 		Description: desc.Description(),
 		Unit:        string(desc.Unit()),
 	}

 	pbLabels := stringKeyValues(labels.Iter())

 	var pts []*metricpb.NumberDataPoint
 	for _, s := range points {
 		pt := &metricpb.NumberDataPoint{
 			Labels:            pbLabels,
 			StartTimeUnixNano: toNanos(record.StartTime()),
 			TimeUnixNano:      toNanos(record.EndTime()),
 		}
 		switch nk {
 		case number.Int64Kind:
 			pt.Value = &metricpb.NumberDataPoint_AsInt{
 				AsInt: s.Number.CoerceToInt64(nk),
 			}
 		case number.Float64Kind:
 			pt.Value = &metricpb.NumberDataPoint_AsDouble{
 				AsDouble: s.Number.CoerceToFloat64(nk),
 			}
 		default:
 			return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, nk)
 		}
 		pts = append(pts, pt)
 	}

 	m.Data = &metricpb.Metric_Gauge{
 		Gauge: &metricpb.Gauge{
 			DataPoints: pts,
 		},
 	}

 	return m, nil
 }

 func numberDataPoint(num number.Number, nk number.Kind, labels []*commonpb.StringKeyValue, start, end time.Time) (*metricpb.NumberDataPoint, error) {
 	pt := &metricpb.NumberDataPoint{
 		Labels:            labels,
 		StartTimeUnixNano: toNanos(start),
 		TimeUnixNano:      toNanos(end),
 	}
 	switch nk {
 	case number.Int64Kind:
 		pt.Value = &metricpb.NumberDataPoint_AsInt{
 			AsInt: num.CoerceToInt64(nk),
 		}
 	case number.Float64Kind:
 		pt.Value = &metricpb.NumberDataPoint_AsDouble{
 			AsDouble: num.CoerceToFloat64(nk),
 		}
 	default:
 		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, nk)
 	}
 	return pt, nil
 }

 func histogramSum(num number.Number, nk number.Kind) (float64, error) {
 	switch nk {
 	case number.Int64Kind:
 		return float64(num.CoerceToInt64(nk)), nil
 	case number.Float64Kind:
 		return num.CoerceToFloat64(nk), nil
 	default:
 		return 0, fmt.Errorf("%w: %v", ErrUnknownValueType, nk)
 	}
 }

 func gaugePoint(record export.Record, num number.Number, start, end time.Time) (*metricpb.Metric, error) {
 	desc := record.Descriptor()
 	labels := record.Labels()
 	nk := desc.NumberKind()

 	pt, err := numberDataPoint(num, nk, stringKeyValues(labels.Iter()), start, end)
 	if err != nil {
 		return nil, err
 	}

 	m := &metricpb.Metric{
 		Name:        desc.Name(),
 		Description: desc.Description(),
 		Unit:        string(desc.Unit()),
 		Data: &metricpb.Metric_Gauge{
 			Gauge: &metricpb.Gauge{
 				DataPoints: []*metricpb.NumberDataPoint{pt},
 			},
 		},
 	}

 	return m, nil
 }

 func exportKindToTemporality(ek export.ExportKind) metricpb.AggregationTemporality {
 	switch ek {
 	case export.DeltaExportKind:
 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_DELTA
 	case export.CumulativeExportKind:
 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_CUMULATIVE
 	}
 	return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_UNSPECIFIED
 }

 func sumPoint(record export.Record, num number.Number, start, end time.Time, ek export.ExportKind, monotonic bool) (*metricpb.Metric, error) {
 	desc := record.Descriptor()
 	labels := record.Labels()
 	nk := desc.NumberKind()

 	pt, err := numberDataPoint(num, nk, stringKeyValues(labels.Iter()), start, end)
 	if err != nil {
 		return nil, err
 	}

 	m := &metricpb.Metric{
 		Name:        desc.Name(),
 		Description: desc.Description(),
 		Unit:        string(desc.Unit()),
 		Data: &metricpb.Metric_Sum{
 			Sum: &metricpb.Sum{
 				IsMonotonic:            monotonic,
 				AggregationTemporality: exportKindToTemporality(ek),
 				DataPoints:             []*metricpb.NumberDataPoint{pt},
 			},
 		},
 	}

 	return m, nil
 }

 // minMaxSumCountValue returns the values of the MinMaxSumCount Aggregator
 // as discrete values.
 func minMaxSumCountValues(a aggregation.MinMaxSumCount) (min, max, sum number.Number, count uint64, err error) {
 	if min, err = a.Min(); err != nil {
 		return
 	}
 	if max, err = a.Max(); err != nil {
 		return
 	}
 	if sum, err = a.Sum(); err != nil {
 		return
 	}
 	if count, err = a.Count(); err != nil {
 		return
 	}
 	return
 }

 // minMaxSumCount transforms a MinMaxSumCount Aggregator into an OTLP Metric.
 func minMaxSumCount(record export.Record, a aggregation.MinMaxSumCount) (*metricpb.Metric, error) {
 	desc := record.Descriptor()
 	labels := record.Labels()
 	min, max, sum, count, err := minMaxSumCountValues(a)
 	if err != nil {
 		return nil, err
 	}

 	sumValue, err := histogramSum(sum, desc.NumberKind())
 	if err != nil {
 		return nil, err
 	}

 	m := &metricpb.Metric{
 		Name:        desc.Name(),
 		Description: desc.Description(),
 		Unit:        string(desc.Unit()),
 	}

 	buckets := []uint64{min.AsRaw(), max.AsRaw()}
 	bounds := []float64{0.0, 100.0}

 	m.Data = &metricpb.Metric_Histogram{
 		Histogram: &metricpb.Histogram{
 			DataPoints: []*metricpb.HistogramDataPoint{
 				{
 					Sum:               sumValue,
 					Labels:            stringKeyValues(labels.Iter()),
 					StartTimeUnixNano: toNanos(record.StartTime()),
 					TimeUnixNano:      toNanos(record.EndTime()),
 					Count:             uint64(count),
 					BucketCounts:      buckets,
 					ExplicitBounds:    bounds,
 				},
 			},
 		},
 	}
 	return m, nil
 }

 func histogramValues(a aggregation.Histogram) (boundaries []float64, counts []uint64, err error) {
 	var buckets aggregation.Buckets
 	if buckets, err = a.Histogram(); err != nil {
 		return
 	}
 	boundaries, counts = buckets.Boundaries, buckets.Counts
 	if len(counts) != len(boundaries)+1 {
 		err = ErrTransforming
 		return
 	}
 	return
 }

 // histogram transforms a Histogram Aggregator into an OTLP Metric.
 func histogramPoint(record export.Record, ek export.ExportKind, a aggregation.Histogram) (*metricpb.Metric, error) {
 	desc := record.Descriptor()
 	labels := record.Labels()
 	boundaries, counts, err := histogramValues(a)
 	if err != nil {
 		return nil, err
 	}

 	count, err := a.Count()
 	if err != nil {
 		return nil, err
 	}

 	sum, err := a.Sum()
 	if err != nil {
 		return nil, err
 	}

 	sumValue, err := histogramSum(sum, desc.NumberKind())
 	if err != nil {
 		return nil, err
 	}

 	m := &metricpb.Metric{
 		Name:        desc.Name(),
 		Description: desc.Description(),
 		Unit:        string(desc.Unit()),
 		Data: &metricpb.Metric_Histogram{
 			Histogram: &metricpb.Histogram{
 				AggregationTemporality: exportKindToTemporality(ek),
 				DataPoints: []*metricpb.HistogramDataPoint{
 					{
 						Sum:               sumValue,
 						Labels:            stringKeyValues(labels.Iter()),
 						StartTimeUnixNano: toNanos(record.StartTime()),
 						TimeUnixNano:      toNanos(record.EndTime()),
 						Count:             uint64(count),
 						BucketCounts:      counts,
 						ExplicitBounds:    boundaries,
 					},
 				},
 			},
 		},
 	}

 	return m, nil
 }

 // stringKeyValues transforms a label iterator into an OTLP StringKeyValues.
 func stringKeyValues(iter attribute.Iterator) []*commonpb.StringKeyValue {
 	l := iter.Len()
 	if l == 0 {
 		return nil
 	}
 	result := make([]*commonpb.StringKeyValue, 0, l)
 	for iter.Next() {
 		kv := iter.Label()
 		result = append(result, &commonpb.StringKeyValue{
 			Key:   string(kv.Key),
